#!/usr/bin/env python3
"""将保留的原始眼睛轮廓转为定点数据。 / Convert preserved eye rings to fixed point."""
from decimal import Decimal
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
source = ROOT / "artwork/mimi/vendor/GrokBot/expression_data.dart"
points = re.findall(r"Offset\(([-\d.]+),\s*([-\d.]+)\)", source.read_text())
if len(points) != 25 * 2 * 48:
    raise ValueError("Expected 25 expressions, two eyes and 48 vertices per eye")
output = [
    "// Generated by tools/gen_mimi_expressions.py; coordinates in 0.01 source units.",
    "// Derived from nasawz/GrokBot bb7b634; Copyright (c) 2026, nasawz (BSD-3-Clause).",
    "// Full notice: artwork/mimi/vendor/GrokBot/LICENSE; provenance: MIMI.md.",
    "static const int16_t mimi_expressions[25][2][MIMI_EYE_POINTS][2] = {",
]
for expression in range(25):
    output.append("    {")
    for eye in range(2):
        start = (expression * 2 + eye) * 48
        ring = points[start : start + 48]
        output.append("        {" + ",".join(
            "{%d,%d}" % (int(Decimal(x) * 100), int(Decimal(y) * 100))
            for x, y in ring
        ) + "},")
    output.append("    },")
output.append("};\n")
(ROOT / "main/mimi_expressions.inc").write_text("\n".join(output))
print("Mimi: 25 expressions, 2 x 48 points; 9,600 bytes of fixed-point coordinates")
